parameters.jsCode:
// Accept leads from a website form, a portal, or a Zapier-style forwarder.
// Normalise the field names once here so the rest of the flow is stable.
const b = $input.first().json.body || $input.first().json;

const name = b.name || b.full_name || b.firstName || 'there';
const email = b.email || b.email_address || null;
const phone = b.phone || b.telephone || null;
const message = b.message || b.enquiry || b.comments || '';
const source = b.source || 'website form';

if (!email && !phone) {
  throw new Error('lead has no email and no phone - nothing to reply to');
}

return [{ json: { name, email, phone, message, source, receivedAt: new Date().toISOString() } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5',
  max_tokens: 400,
  system: `You write the first reply to a new enquiry for ${$env.BUSINESS_NAME}. Rules: reply in 3-5 short sentences; answer their actual question if the business information below covers it, otherwise acknowledge it specifically and say a colleague will confirm; always invite them to book using the link; never invent prices, availability or promises; sign off as the ${$env.BUSINESS_NAME} team. Write plain text, no subject line, no markdown.

BUSINESS INFORMATION:
${$env.BUSINESS_BLURB}

BOOKING LINK: ${$env.BOOKING_LINK}`,
  messages: [{ role: 'user', content: `New enquiry from ${$json.name} via ${$json.source}.

Their message: ${$json.message || '(no message provided)'}` }]
}) }}

parameters.jsCode:
const reply = $json.content?.filter(b => b.type === 'text').map(b => b.text).join('').trim();
const lead = $('Normalise Lead').first().json;

if (!reply) {
  throw new Error('no reply text returned - not sending an empty email');
}

return [{ json: { ...lead, reply } }];

